<?php
namespace App\Modules\Sales\Application;
use App\Models\User;use App\Modules\CashManagement\Domain\Enums\CashSessionStatus;use App\Modules\CashManagement\Domain\Models\CashSession;use App\Modules\Finance\Application\Data\JournalEntryData;use App\Modules\Finance\Application\Data\JournalLineData;use App\Modules\Finance\Application\PostJournalEntry;use App\Modules\Finance\Domain\Enums\FinancialDocumentStatus;use App\Modules\Finance\Domain\Enums\PaymentDirection;use App\Modules\Finance\Domain\Models\FinancialAccount;use App\Modules\Finance\Domain\Models\Payment;use App\Modules\Sales\Domain\Enums\ReceivableStatus;use App\Modules\Sales\Domain\Enums\SaleStatus;use App\Modules\Sales\Domain\Models\Receivable;use App\Modules\Sales\Domain\Models\Sale;use App\Modules\Shared\Application\NextDocumentNumber;use Carbon\CarbonInterface;use DomainException;use Illuminate\Support\Facades\DB;
class PayReceivable {public function __construct(private readonly NextDocumentNumber $numbers,private readonly PostJournalEntry $journal){}public function execute(Receivable $receivable,int $amount,string $accountId,CarbonInterface $paidAt,User $actor,?string $reference=null):Payment{return DB::transaction(function()use($receivable,$amount,$accountId,$paidAt,$actor,$reference){$receivable=Receivable::query()->lockForUpdate()->findOrFail($receivable->id);if($amount<=0||$amount>$receivable->balance_amount)throw new DomainException('El abono debe ser positivo y no superar el saldo.');$account=FinancialAccount::query()->where('accepts_payments',true)->where('is_active',true)->findOrFail($accountId);if($account->code==='1105-CAJA-MENOR'&&!CashSession::query()->where('financial_account_id',$account->id)->where('status',CashSessionStatus::Open)->exists())throw new DomainException('Debes abrir la caja menor antes de recibir efectivo.');$payment=Payment::create(['document_number'=>$this->numbers->execute('receivable_payment','ABO',$paidAt),'direction'=>PaymentDirection::Incoming,'person_id'=>$receivable->person_id,'paid_at'=>$paidAt,'amount'=>$amount,'financial_account_id'=>$account->id,'status'=>FinancialDocumentStatus::Confirmed,'reference'=>$reference,'created_by'=>$actor->id]);$payment->allocations()->create(['allocatable_type'=>$receivable->getMorphClass(),'allocatable_id'=>$receivable->id,'amount'=>$amount]);$paid=$receivable->paid_amount+$amount;$balance=$receivable->balance_amount-$amount;$receivable->update(['paid_amount'=>$paid,'balance_amount'=>$balance,'status'=>$balance===0?ReceivableStatus::Paid:ReceivableStatus::Partial]);if($receivable->source instanceof Sale){$sale=$receivable->source;$salePaid=$sale->paid_amount+$amount;$sale->update(['paid_amount'=>$salePaid,'balance_amount'=>$sale->balance_amount-$amount,'status'=>$balance===0?SaleStatus::Paid:SaleStatus::PartiallyPaid]);}$cxc=FinancialAccount::query()->where('code','1305-CXC')->sole();$this->journal->execute(new JournalEntryData($paidAt,"Abono {$payment->document_number}",$actor,[new JournalLineData($account->id,$amount,0,$receivable->person_id,'Entrada de dinero'),new JournalLineData($cxc->id,0,$amount,$receivable->person_id,'Disminución de cartera')],$payment));return $payment->load('allocations');});}}
